[{"unit_id": "nk2.ch26-5.art346-51.p1-2.sp3", "kind": "subpoint", "label": "подпункт 3 пункта 1.2 статьи 346.51 НК РФ", "title": null, "context": "НК РФ, часть 1, раздел VIII.1 «Специальные налоговые режимы», глава 26.5 «ПАТЕНТНАЯ СИСТЕМА НАЛОГООБЛОЖЕНИЯ», статья 346.51 «Порядок исчисления налога, порядок и сроки уплаты налога»", "pass": "loose", "rank": 0.0267, "snippet": "деятельности, в пользу работников на случай их временной нетрудоспособности (за исключением несчастных случаев на производстве и профессиональных заболеваний) за «дни» временной нетрудоспособности, которые оплачиваются за счет средств работодателя и число которых установлено Федеральным законом от 29 декабря 2006 года ... законодательством Российской Федерации размера пособия по временной нетрудоспособности (за исключением несчастных случаев на производстве и профессиональных заболеваний) за «дни» временной нетрудоспособности работника, которые оплачиваются за счет средств работодателя и число которых установлено Федеральным законом от 29 декабря 2006 года", "sources": ["lexical", "dense"]}, {"unit_id": "nk2.ch25-4.art333-46.p2", "kind": "point", "label": "пункт 2 статьи 333.46 НК РФ", "title": null, "context": "НК РФ, часть 1, раздел VIII «ФЕДЕРАЛЬНЫЕ НАЛОГИ», глава 25.4 «НАЛОГ НА ДОПОЛНИТЕЛЬНЫЙ ДОХОД ОТ ДОБЫЧИ УГЛЕВОДОРОДНОГО СЫРЬЯ», статья 333.46 «Порядок определения расчетной выручки от реализации»", "pass": "loose", "rank": 0.0251, "snippet": "Расчетная выручка от реализации углеводородного сырья, добытого на участке недр, за «календарный» месяц (Вр-месяц) определяется по следующей формуле:

Вр-месяц = Цнефть x Vнк x Р x Кн + Цгаз x Vгаз + 0,95 x Цпнг x Vпнг,

